    await p.goto('http://10.17.1.66:3001/en', {waitUntil:'domcontentloaded'});
    await p.waitForTimeout(8000);
    globalThis.__mp = p;
  }
  const r = await p.evaluate(() => {
    const html = document.documentElement.outerHTML;
    const hits = [];
    const re = /butt/gi;
    let m;
    while ((m = re.exec(html)) && hits.length < 6) hits.push(html.slice(Math.max(0, m.index - 90), m.index + 60));
    const sect = Array.from(document.querySelectorAll('section,div')).find(d => (d.innerText||'').startsWith('Create Faster with'));
    const cards = sect ? Array.from(sect.querySelectorAll('button,img[alt]')).slice(0, 30).map(e => e.tagName + '|' + ((e.innerText||e.getAttribute('alt')||'').trim().slice(0,40))) : [];
    const fileInputs = document.querySelectorAll('input[type=file]').length;
    return {buttHits: hits, cardCount: cards.length, cards: cards, fileInputs: fileInputs};
  });
  return JSON.stringify(r);
}
